{
  "fields": [
    {
      "id": "space_count",
      "value": 48,
      "evidence": "Rent-Roll.xlsx | Rows C7:C54 list units 101–148 (48 total)",
      "calculation": "Count of unique Unit/suite entries (101–148) = 48"
    },
    {
      "id": "occupied_count",
      "value": 33,
      "evidence": "Rent-Roll.xlsx | F7:F40 show 33 units with Status='Occupied' (101–133); 134–148 are 'Vacant'",
      "calculation": "Occupied units = 33"
    },
    {
      "id": "total_area_sf",
      "value": 43200,
      "evidence": "Rent-Roll.xlsx | E7:E54 (areas per unit)",
      "calculation": "24 units × 700 sf + 24 units × 1100 sf = 16,800 sf + 26,400 sf = 43,200 sf"
    },
    {
      "id": "occupied_area_sf",
      "value": 26700,
      "evidence": "Rent-Roll.xlsx | E7:E39 (occupied units 101–133)",
      "calculation": "24 occupied units × 700 sf + 9 occupied units × 1100 sf = 16,800 sf + 9,900 sf = 26,700 sf"
    },
    {
      "id": "occupancy_count_pct",
      "value": 68.75,
      "evidence": "Rent-Roll.xlsx | Occupied count 33; total count 48",
      "calculation": "(33 / 48) × 100 = 68.75%"
    },
    {
      "id": "occupancy_area_pct",
      "value": 61.81,
      "evidence": "Rent-Roll.xlsx | Occupied area 26,700 sf; total area 43,200 sf",
      "calculation": "(26,700 / 43,200) × 100 = 61.8056% ≈ 61.81%"
    },
    {
      "id": "rent_roll_monthly_base",
      "value": 56025,
      "evidence": "Rent-Roll.xlsx | G7:G39 (occupied units’ Monthly base rent); G40:G54 vacant have no contractual rent",
      "calculation": "24 units × $1,575 + 9 units × $2,025 = $37,800 + $18,225 = $56,025/month"
    },
    {
      "id": "effective_monthly_base",
      "value": 56025,
      "evidence": "Lease-File.pdf p.1 (Unit 101 base rent $1,575 as of 2026-08-31, no increase before 2027-09-01); Rent-Roll.xlsx G7:G39",
      "calculation": "No lease amendments provided other than Unit 101; effective equals printed rent roll for occupied units; $0 for vacancies. Total = $56,025/month"
    },
    {
      "id": "t12_egi",
      "value": 691200,
      "evidence": "T12-Statement.pdf p.2 (Annual totals): GPBR 1,036,800; Vacancy (302,400); Concessions (64,800); Bad debt (8,400); Other income 30,000",
      "calculation": "1,036,800 - 302,400 - 64,800 - 8,400 + 30,000 = 691,200"
    },
    {
      "id": "t12_operating_expenses",
      "value": 371200,
      "evidence": "T12-Statement.pdf p.2 (Annual): Taxes 132,000; Insurance 40,800; Utilities 33,600; R&M 54,000; Payroll 55,200; Admin 27,600; Mgmt 28,000",
      "calculation": "132,000 + 40,800 + 33,600 + 54,000 + 55,200 + 27,600 + 28,000 = 371,200"
    },
    {
      "id": "t12_noi_before_reserves",
      "value": 320000,
      "evidence": "Derived from T12-Statement.pdf p.2",
      "calculation": "EGI 691,200 - OpEx 371,200 = 320,000"
    },
    {
      "id": "t12_reserves",
      "value": 14400,
      "evidence": "T12-Statement.pdf p.2 (Replacement reserves annual total)",
      "calculation": "Reported annual replacement reserves = 14,400"
    },
    {
      "id": "t12_ncf",
      "value": 305600,
      "evidence": "Derived from T12-Statement.pdf p.2",
      "calculation": "NOI before reserves 320,000 - Reserves 14,400 = 305,600"
    },
    {
      "id": "uw_egi",
      "value": 1025280,
      "evidence": "Property-and-Plan.pdf p.2 (Underwriting plan: GPBR $1,056,000; combined revenue loss 7%; other income $43,200)",
      "calculation": "1,056,000 × (1 - 0.07) + 43,200 = 982,080 + 43,200 = 1,025,280"
    },
    {
      "id": "uw_management_fee",
      "value": 35884.8,
      "evidence": "Property-and-Plan.pdf p.2 (Management fee: greater of T12 actual $28,000 and 3.5% of underwritten EGI)",
      "calculation": "max(28,000, 3.5% × 1,025,280) = max(28,000, 35,884.80) = 35,884.80"
    },
    {
      "id": "uw_operating_expenses",
      "value": 377884.8,
      "evidence": "Property-and-Plan.pdf p.2 (Underwriting treatment by category)",
      "calculation": "Taxes 138,000 + Insurance 45,600 + Utilities 33,600 + R&M (54,000 - 12,000 one-time) 42,000 + Payroll 55,200 + Admin 27,600 + Mgmt 35,884.80 = 377,884.80"
    },
    {
      "id": "uw_noi_before_reserves",
      "value": 647395.2,
      "evidence": "Derived from underwriting plan inputs",
      "calculation": "UW EGI 1,025,280 - UW OpEx 377,884.80 = 647,395.20"
    },
    {
      "id": "uw_reserves",
      "value": 15600,
      "evidence": "Property-and-Plan.pdf p.2 (Reserves $325 per unit per year); Rent-Roll.xlsx (48 units)",
      "calculation": "$325 × 48 units = $15,600"
    },
    {
      "id": "uw_ncf",
      "value": 631795.2,
      "evidence": "Derived from underwriting plan inputs",
      "calculation": "UW NOI before reserves 647,395.20 - Reserves 15,600 = 631,795.20"
    },
    {
      "id": "capitalization_value",
      "value": 11259046.96,
      "evidence": "Lender-Terms.pdf p.1 (Value = UW NOI BEFORE reserves / 5.75% cap)",
      "calculation": "647,395.20 / 0.0575 = 11,259,046.96"
    },
    {
      "id": "contract_rate",
      "value": 0.0625,
      "evidence": "Lender-Terms.pdf p.1 (Contract rate 6.25% fixed)",
      "calculation": "As stated"
    },
    {
      "id": "sizing_rate",
      "value": 0.065,
      "evidence": "Lender-Terms.pdf p.1 (Sizing rate = greater of contract and 6.50% floor)",
      "calculation": "max(0.0625, 0.0650) = 0.0650"
    },
    {
      "id": "annual_debt_constant",
      "value": 0.075865,
      "evidence": "Lender-Terms.pdf p.1 (30-year, monthly payments; sizing rate 6.50%)",
      "calculation": "Monthly i = 0.065/12; Monthly factor = i / (1 - (1+i)^-360) ≈ 0.006322; Annual constant = 12 × 0.006322 ≈ 0.075865"
    },
    {
      "id": "ltv_limit",
      "value": 6755428.18,
      "evidence": "Lender-Terms.pdf p.1 (LTV 60% of indicative value)",
      "calculation": "0.60 × 11,259,046.96 = 6,755,428.18"
    },
    {
      "id": "dscr_limit",
      "value": 6406067.5,
      "evidence": "Lender-Terms.pdf p.1 (DSCR ≥1.30x using NCF/annual amortizing DS at sizing rate)",
      "calculation": "Max DS = 631,795.20 / 1.30 = 485,996.31; Max loan = 485,996.31 / 0.075865 ≈ 6,406,067.50"
    },
    {
      "id": "debt_yield_limit",
      "value": 7019946.67,
      "evidence": "Lender-Terms.pdf p.1 (Debt yield ≥9.00%; numerator UW NCF after reserves)",
      "calculation": "631,795.20 / 0.09 = 7,019,946.67"
    },
    {
      "id": "maximum_loan",
      "value": 6406067.5,
      "evidence": "Lender-Terms.pdf p.1 (Loan ceiling = lowest of LTV, DSCR, debt yield)",
      "calculation": "min(6,755,428.18, 6,406,067.50, 7,019,946.67) = 6,406,067.50"
    },
    {
      "id": "binding_constraint",
      "value": "DSCR",
      "evidence": "Comparison of the three sizing constraints above",
      "calculation": "DSCR limit is the minimum"
    },
    {
      "id": "sizing_annual_debt_service",
      "value": 485996.31,
      "evidence": "Derived at maximum_loan using sizing rate and amortization",
      "calculation": "6,406,067.50 × 0.075865 = 485,996.31"
    },
    {
      "id": "sizing_dscr",
      "value": 1.3,
      "evidence": "Lender-Terms.pdf p.1 (DSCR definition) and computed DS",
      "calculation": "UW NCF 631,795.20 / 485,996.31 = 1.30x"
    },
    {
      "id": "sizing_debt_yield",
      "value": 0.09866,
      "evidence": "Lender-Terms.pdf p.1 (Debt yield = NCF after reserves / loan)",
      "calculation": "631,795.20 / 6,406,067.50 = 0.09866 (9.866%)"
    },
    {
      "id": "first_year_debt_service",
      "value": 400379.22,
      "evidence": "Lender-Terms.pdf p.1 (36 months interest-only; contractual rate 6.25%)",
      "calculation": "Interest-only Year 1 = 6,406,067.50 × 0.0625 = 400,379.22"
    },
    {
      "id": "cash_to_borrower",
      "value": 1777006.83,
      "evidence": "Property-and-Plan.pdf p.1 (Existing payoff $4,500,000; Fixed closing $65,000); Lender-Terms.pdf p.1 (1.00% origination fee)",
      "calculation": "Net = Loan 6,406,067.50 - Payoff 4,500,000 - Origination (1% × 6,406,067.50 = 64,060.68) - Closing 65,000 = 1,777,006.83"
    },
    {
      "id": "stress_uw_noi",
      "value": 597925.44,
      "evidence": "Property-and-Plan.pdf p.2 (Sensitivity instruction: reduce EGI by 5%, recompute management; others unchanged)",
      "calculation": "Stressed EGI = 1,025,280 × 0.95 = 974,016; Stressed Mgmt = max(28,000, 3.5%×974,016=34,090.56) = 34,090.56; Stressed OpEx = 377,884.80 - 35,884.80 + 34,090.56 = 376,090.56; Stressed NOI = 974,016 - 376,090.56 = 597,925.44"
    },
    {
      "id": "stress_maximum_loan",
      "value": 5339210,
      "evidence": "Property-and-Plan.pdf p.2 (Sensitivity); Lender-Terms.pdf p.1 (sizing definitions)",
      "calculation": "With EGI -5%: Stressed NCF = 597,925.44 - 15,600 = 582,325.44. Sizing rate +100 bps => 7.50% (30-yr monthly), annual constant ≈ 0.083916. Constraints: LTV = 0.60 × (597,925.44/0.0575) = $6,239,221.98; DSCR = (582,325.44/1.30)/0.083916 = $5,339,210; Debt yield = 582,325.44/0.09 = $6,470,282.67. Minimum = $5,339,210 (DSCR)."
    },
    {
      "id": "subject_lease_monthly_rent",
      "value": 1575,
      "evidence": "Lease-File.pdf p.1 (Premises 101 base rent $1,575 as of 2026-08-31); Rent-Roll.xlsx G7",
      "calculation": "As stated in executed lease; matches rent roll"
    },
    {
      "id": "subject_lease_expiry",
      "value": "2027-06-30",
      "evidence": "Lease-File.pdf p.1 (Initial term expires 2027-06-30); Rent-Roll.xlsx I7",
      "calculation": "As stated"
    },
    {
      "id": "subject_lease_deposit",
      "value": 1200,
      "evidence": "Lease-File.pdf p.1 (Security deposit $1,200)",
      "calculation": "As stated"
    },
    {
      "id": "verified_renewal_insurance",
      "value": 45600,
      "evidence": "Property-and-Plan.pdf p.2 (Fictional insurer renewal confirmation: annual premium $45,600; use in underwriting)",
      "calculation": "As stated"
    },
    {
      "id": "renewal_option_exercised",
      "value": false,
      "evidence": "Lease-File.pdf p.1 §5 (No exercise notice or amendment included; do not extend expiry based on option alone)",
      "calculation": "No evidence of exercise provided"
    },
    {
      "id": "prepayment_friction",
      "value": "1% of outstanding principal if prepaid in years 1–2; no stated bank penalty thereafter; no swap assumed.",
      "evidence": "Lender-Terms.pdf p.1 (Prepayment terms)",
      "calculation": "As stated"
    }
  ],
  "qualifications": [
    "Only the Unit 101 executed lease was provided; other unit economics rely on the rent roll without separate executed leases. Effective monthly base equals the rent roll amounts except where lease amendments are evidenced (only Unit 101 provided).",
    "Historical T12 figures are taken as reported; the T12 'property NOI' label (if any) was not used for underwriting metrics. We derived NOI before reserves and NCF after reserves per instructions.",
    "Underwriting follows the scenario in Property-and-Plan.pdf; no external market data, comps, or geocoding were used.",
    "Debt-service constants are computed for 30-year monthly amortization at the indicated sizing rates. Minor rounding may occur; sizing uses the stated methodology.",
    "First-year contractual debt service reflects 36 months interest-only at the contractual rate (6.25%); underwriting DSCR still uses amortizing debt service per the term sheet.",
    "Stress sizing applies both EGI -5% with management recalculated and +100 bps to the sizing rate; all other expense and reserve assumptions held constant; cap rate unchanged for stress value.",
    "All details are fictional and limited to the supplied packet; no contact with third parties and no external research were performed."
  ],
  "summary": "As of 2026-08-31, Cedar Landing shows 33/48 units occupied (68.75% by count; 61.81% by area) and $56,025/month contractual base rent on the rent roll. T12 EGI is $691,200 with T12 NOI before reserves of $320,000 and NCF of $305,600. The supplied underwriting scenario yields EGI $1,025,280, operating expenses $377,884.80 (including a 3.5% management fee floor), NOI before reserves $647,395.20 and NCF $631,795.20. Indicative value at a 5.75% cap on UW NOI before reserves is $11.26 million. Loan sizing per the term sheet: LTV limit $6.76mm; DSCR limit $6.41mm; Debt yield limit $7.02mm. The binding constraint is DSCR at an estimated $6,406,067.50. At this maximum loan, underwriting DSCR is 1.30x, debt yield ~9.87%, and first-year (IO) contractual debt service is ~$400.38k versus the sizing amortizing debt service of ~$486.00k. Net cash to the borrower after a $4.50mm payoff, 1.00% origination fee, and $65k fixed closing costs is approximately $1.78mm. In the combined downside (EGI -5% with management recalculated and +100 bps sizing rate), the DSCR constraint remains binding with a stressed maximum loan of about $5.34mm; stressed NOI before reserves is ~$597.93k. Unit 101’s executed lease confirms $1,575/month rent, expiry 2027-06-30, and a $1,200 deposit; no renewal option exercise is evidenced. Verified renewal insurance premium is $45,600 annually. Prepayment: 1% of outstanding principal if prepaid in years 1–2; no stated bank penalty thereafter; no swap assumed.",
  "blocked": [
    "Downloadable XLSX underwriting workbook with editable assumptions and live formulas: blocked (this control has no artifact-generation tools).",
    "Concise, polished financing memorandum delivered as a PDF or native memo: blocked (no document/PDF creation tools in this control)."
  ]
}
